"""Copy generated bytes and create independent review artifacts; never edit assets."""
from pathlib import Path
from PIL import Image, ImageDraw
import hashlib, json, shutil, sys

root = Path(__file__).parent
job = json.loads(Path(sys.argv[1]).read_text(encoding='utf-8'))
out = root/'review'/job['theme']
out.mkdir(parents=True,exist_ok=True)
manifest_path=root/'manifest.json'
manifest=json.loads(manifest_path.read_text(encoding='utf-8'))
item=next(x for x in manifest['items'] if x['number']==job['number'])
source=Path(job['source_root'])/item['source']
assert hashlib.sha256(source.read_bytes()).hexdigest()==item['source_sha256']
inventory_path=out/'inventory.json'
inventory=json.loads(inventory_path.read_text(encoding='utf-8')) if inventory_path.exists() else dict(source_number=job['number'],source_file=item['source'],source_sha256=item['source_sha256'],generator='built-in image_gen',assets=[])
for asset in job['assets']:
    target=out/asset['filename']
    shutil.copyfile(asset['generated_path'],target)
    im=Image.open(target)
    assert im.mode=='RGBA', im.mode
    alpha=im.getchannel('A'); hist=alpha.histogram()
    edges=[alpha.crop((0,0,im.width,1)),alpha.crop((0,im.height-1,im.width,im.height)),alpha.crop((0,0,1,im.height)),alpha.crop((im.width-1,0,im.width,im.height))]
    data=target.read_bytes()
    rec=dict(file=target.name,dimensions=im.size,mode=im.mode,bytes=len(data),sha256=hashlib.sha256(data).hexdigest(),git_blob_sha1=hashlib.sha1(b'blob '+str(len(data)).encode()+b'\0'+data).hexdigest(),transparent_pixels=hist[0],partial_alpha_pixels=sum(hist[1:255]),opaque_pixels=hist[255],alpha_bbox=alpha.getbbox(),edge_nonzero_pixels=dict(zip(['top','bottom','left','right'],[sum(x.histogram()[1:]) for x in edges])),visual_review=asset['visual_review'],status=asset['status'],final_approved=False,prompt=asset.get('prompt','See source-specific QA report'))
    inventory['assets']=[x for x in inventory['assets'] if x['file']!=target.name]+[rec]
    panels=[]
    for bg_color in ['white','black','#777777']:
        panel=Image.new('RGBA',im.size,bg_color);panel.alpha_composite(im);panel.thumbnail((1200,1000));panels.append(panel.convert('RGB'))
    ref=Image.open(source).convert('RGB');ref.thumbnail((1200,900))
    qa=Image.new('RGB',(1200,40+ref.height+sum(x.height+25 for x in panels)),'#cccccc')
    qa.paste(ref,(0,25));draw=ImageDraw.Draw(qa);draw.text((5,5),'SOURCE / WHITE / BLACK / GRAY - REVIEW ONLY',fill='black');y=40+ref.height
    for panel in panels:qa.paste(panel,(0,y));y+=panel.height+25
    qa.save(out/(target.stem+'_comparison.jpg'),quality=94)
inventory['final_approved']=False
inventory_path.write_text(json.dumps(inventory,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
item.update(status='review_assets_saved_not_fully_identical',review_directory=out.relative_to(root.parent.parent.parent).as_posix()+'/',review_png_count=len(inventory['assets']),visual_qa='not_final_approved_see_inventory',alpha_qa='measured_not_final_approved',final_approved=False)
manifest['current_batch']=f"No.{job['number']} review work in progress; final approval separate"
manifest_path.write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps(dict(number=job['number'],saved=[x['file'] for x in inventory['assets']],final_approved=False),ensure_ascii=False))
